Q: Angular/RxJS 6: How to prevent duplicate HTTP requests? A: <p>I think you would achieve by doing something like this:</p>
<pre><code>class SharedService {
  yourData: any;
  private cache$: ReplaySubject&lt;any&gt; | null = null;
  constructor(private http: HttpClient) {}


  getSomeData(): Observable&lt;any&gt; {
    if(this.yourData){
     return of(this.yourData);   
    }
    if (this.cache$) {
      return this.cache$.pipe(first());
    }
    this.cache$ = new ReplaySubject&lt;any&gt;(1)
    return this.http.get&lt;any&gt;('some/endpoint')
    .pipe(
        tap((resp) =&gt; {
            this.yourData = resp;
            this.cache$?.next(resp);
            this.cache$?.complete();
        }),
        shareReplay({ bufferSize: 1, refCount: false })
    );
  }
}

class Component1 {
  constructor(private sharedService: SharedService) {
    this.sharedService.getSomeData().subscribe(
      () =&gt; console.log('do something...')
    );
  }
}

class Component2 {
  constructor(private sharedService: SharedService) {
    this.sharedService.getSomeData().subscribe(
      () =&gt; console.log('do something different...')
    );
  }
}
</code></pre>
